const fs = require('fs');
const path = require('path');

// Generated by scripts/build-word-db.js from server/src/words/categories/*.json.
// Never edit these four files directly; edit the category source files instead.
const easyWords = require('./words/easy.json');
const mediumWords = require('./words/medium.json');
const hardWords = require('./words/hard.json');
const expertWords = require('./words/expert.json');

const PACK_DEFINITIONS = require('../../shared/wordPacks.json');

const ALLOWED_DIFFICULTIES = ['Easy', 'Medium', 'Hard', 'Expert', 'Mixed'];
const ALLOWED_PACKS = PACK_DEFINITIONS.map(p => p.id);

const LEVELS = [
    { label: 'Easy', level: 1, words: easyWords },
    { label: 'Medium', level: 2, words: mediumWords },
    { label: 'Hard', level: 3, words: hardWords },
    { label: 'Expert', level: 4, words: expertWords }
];

const wordLists = {
    Easy: easyWords,
    Medium: mediumWords,
    Hard: hardWords,
    Expert: expertWords
};

// Pack word sets are built from the category source files so a pack always
// reflects the current database without a separate generated artifact.
const categoryWords = {};
const categoriesDir = path.join(__dirname, 'words', 'categories');
for (const file of fs.readdirSync(categoriesDir)) {
    if (!file.endsWith('.json')) continue;
    const categoryId = path.basename(file, '.json');
    categoryWords[categoryId] = require(path.join(categoriesDir, file));
}

const packs = {};
const packSets = {};
for (const def of PACK_DEFINITIONS) {
    const set = new Set();
    for (const categoryId of def.categories) {
        const category = categoryWords[categoryId];
        if (!category) continue;
        for (const words of Object.values(category)) {
            for (const word of words) set.add(word);
        }
    }
    packSets[def.id] = set;
    packs[def.id] = Array.from(set).sort();
}

// Map word -> { difficulty, level }
const difficultyMap = new Map();
for (const { label, level, words } of LEVELS) {
    for (const word of words) difficultyMap.set(word, { difficulty: label, level });
}

function getWordDifficulty(word) {
    if (!word || typeof word !== 'string') {
        return { difficulty: 'Medium', level: 2 };
    }
    return difficultyMap.get(word.trim().toLowerCase()) || { difficulty: 'Medium', level: 2 };
}

/**
 * Fisher-Yates shuffle algorithm. Operates on a shallow copy.
 * Never sorts or mutates the source array.
 */
function shuffle(array) {
    if (!Array.isArray(array)) return [];
    const copy = array.slice();
    for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const temp = copy[i];
        copy[i] = copy[j];
        copy[j] = temp;
    }
    return copy;
}

const TIER_WEIGHTS = { Easy: 3, Medium: 3, Hard: 2, Expert: 2 };

function pickWeightedTier() {
    const tiers = ['Easy', 'Medium', 'Hard', 'Expert'];
    const total = tiers.reduce((sum, tier) => sum + TIER_WEIGHTS[tier], 0);
    let roll = Math.random() * total;
    for (const tier of tiers) {
        roll -= TIER_WEIGHTS[tier];
        if (roll < 0) return tier;
    }
    return 'Medium';
}

function resetUsedWordsExceptRecent(room, keep = 10) {
    const recent = Array.from(room.usedWords).slice(-keep);
    room.usedWords.clear();
    for (const word of recent) room.usedWords.add(word);
}

/**
 * getWordChoices(room, count = 3)
 * Builds candidate pools from room.settings.difficulty and room.settings.packs.
 * Excludes room.usedWords and softly avoids words in room.recentChoices.
 * Resets usedWords to the last 10 words if a pool runs dry.
 * Mixes in customWords at roughly 30% weight.
 * Mixed difficulty guarantees distinct tiers (Easy/Medium plus Hard/Expert).
 */
function getWordChoices(room = {}, count = 3) {
    if (!room.usedWords || !(room.usedWords instanceof Set)) {
        room.usedWords = new Set();
    }
    if (!Array.isArray(room.recentChoices)) {
        room.recentChoices = [];
    }

    const difficulty = room?.settings?.difficulty || 'Medium';
    const rawPacks = Array.isArray(room?.settings?.packs) ? room.settings.packs : [];
    const activePacks = rawPacks.filter(p => ALLOWED_PACKS.includes(p));
    const recentSet = new Set(room.recentChoices);

    const filterByPacks = (wordList) => {
        if (activePacks.length === 0) return wordList;
        const filtered = wordList.filter(w => activePacks.some(p => packSets[p]?.has(w)));
        return filtered.length > 0 ? filtered : wordList;
    };

    const taken = new Set();

    const takeFromPool = (basePool, need) => {
        if (need <= 0 || basePool.length === 0) return [];
        let available = basePool.filter(w => !room.usedWords.has(w) && !taken.has(w));
        if (available.length < need) {
            resetUsedWordsExceptRecent(room);
            available = basePool.filter(w => !room.usedWords.has(w) && !taken.has(w));
            if (available.length < need) {
                available = basePool.filter(w => !taken.has(w));
            }
        }
        const fresh = available.filter(w => !recentSet.has(w));
        const source = fresh.length >= need ? fresh : available;
        const picks = shuffle(source).slice(0, need);
        for (const word of picks) taken.add(word);
        return picks;
    };

    // Custom words: ~30% of the choices, never more than requested.
    const customWords = Array.isArray(room?.settings?.customWords) ? room.settings.customWords : [];
    let pickedCustom = [];
    if (customWords.length > 0 && count > 0) {
        let availableCustom = customWords.filter(w => !room.usedWords.has(w));
        if (availableCustom.length < 1) {
            resetUsedWordsExceptRecent(room);
            availableCustom = customWords.filter(w => !room.usedWords.has(w));
            if (availableCustom.length < 1) availableCustom = customWords.slice();
        }
        const customTarget = count === 1
            ? (Math.random() < 0.3 ? 1 : 0)
            : Math.min(availableCustom.length, Math.max(1, Math.round(count * 0.3)));
        pickedCustom = shuffle(availableCustom).slice(0, customTarget);
        for (const word of pickedCustom) taken.add(word);
    }

    const needed = Math.max(0, count - pickedCustom.length);
    const pools = {
        Easy: filterByPacks(easyWords),
        Medium: filterByPacks(mediumWords),
        Hard: filterByPacks(hardWords),
        Expert: filterByPacks(expertWords)
    };
    let standard = [];

    if (needed > 0) {
        if (difficulty === 'Mixed') {
            if (needed >= 3) {
                const thirdTier = Math.random() < 0.5 ? 'Hard' : 'Expert';
                standard = [
                    ...takeFromPool(pools.Easy, 1),
                    ...takeFromPool(pools.Medium, 1),
                    ...takeFromPool(pools[thirdTier], 1)
                ];
                if (needed > 3) {
                    standard.push(...takeFromPool(pools[thirdTier], needed - 3));
                }
            } else if (needed === 2) {
                // One approachable tier plus one challenging tier.
                const lightTier = Math.random() < 0.5 ? 'Easy' : 'Medium';
                const heavyTier = Math.random() < 0.5 ? 'Hard' : 'Expert';
                standard = [
                    ...takeFromPool(pools[lightTier], 1),
                    ...takeFromPool(pools[heavyTier], 1)
                ];
            } else {
                standard = takeFromPool(pools[pickWeightedTier()], 1);
            }
        } else {
            const targetPool = pools[difficulty] || pools.Medium;
            standard = takeFromPool(targetPool, needed);
        }
    }

    const choices = shuffle([...pickedCustom, ...standard]);
    room.recentChoices = [...room.recentChoices, ...choices].slice(-24);
    return choices;
}

const getRandomWords = (count = 3, difficulty = 'Medium') => {
    const mockRoom = { settings: { difficulty, packs: [] }, usedWords: new Set() };
    return getWordChoices(mockRoom, count);
};

module.exports = {
    words: wordLists,
    packs,
    PACK_DEFINITIONS,
    ALLOWED_DIFFICULTIES,
    ALLOWED_PACKS,
    getWordChoices,
    getWordDifficulty,
    getRandomWords,
    shuffle
};
